export function createWordReader({load,matches,fa,select,view,toast}){
 const $=id=>document.getElementById(id);let lexicon,roots,searchLimit=50,rootEntries=[],rootLimit=100,rootTicket=0;
 function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
 async function init(){[lexicon,roots]=await Promise.all([load('kalemat/lexicon.json'),load('kalemat/roots.json')]);$('words-total').textContent=`${fa(lexicon.length)} صورت و معنی واژه · ${fa(roots.length)} ریشه`;search();}
 async function showRoot(id){const ticket=++rootTicket;view('words');$('root-occurrences').textContent='در حال خواندن کاربردهای ریشه…';const row=await load(`kalemat/roots/${id}.json`);if(ticket!==rootTicket)return;rootEntries=row.occurrences;rootLimit=100;$('root-title').textContent=`ریشهٔ ${row.display||row.root} · ${fa(rootEntries.length)} کاربرد در این بانک`;renderOccurrences();}
 function renderOccurrences(){const frag=document.createDocumentFragment();for(const row of rootEntries.slice(0,rootLimit)){const b=el('button',undefined,'word-occurrence');b.append(el('strong',row.arabic),el('span',row.meaning),el('small',`سورهٔ ${fa(row.surah)}، آیهٔ ${fa(row.ayah)}`));b.onclick=()=>select(row.surah,row.ayah);frag.append(b);}$('root-occurrences').replaceChildren(frag);$('root-more').hidden=rootEntries.length<=rootLimit;}
 function search(){if(!lexicon)return;const query=$('words-search').value;const rows=lexicon.filter(w=>matches([w.arabic,w.meaning,w.root,w.rootDisplay].join(' '),query));$('word-result-count').textContent=`${fa(rows.length)} نتیجه؛ نمایش ${fa(Math.min(searchLimit,rows.length))} مورد`;$('word-results').replaceChildren();for(const word of rows.slice(0,searchLimit)){const card=el('article',undefined,'word-card');card.append(el('h3',word.arabic),el('p',word.meaning));const root=el('button',`ریشه: ${word.rootDisplay||word.root}`);root.onclick=()=>showRoot(word.rootId).catch(e=>toast(e.message));const go=el('button','نمونه در قرآن');go.onclick=()=>select(word.firstOccurrence.surah,word.firstOccurrence.ayah);card.append(root,go);$('word-results').append(card);}$('words-more').hidden=rows.length<=searchLimit;}
 async function renderVerse(ayah){
 const [complete,selected]=await Promise.all([load(`full-words/surahs/${ayah.surah_id}.json`),load(`kalemat/surahs/${ayah.surah_id}.json`)]),v=complete.verses[ayah.number],node=el('div');
 node.append(el('p','معنی واژه‌ها و عبارت‌های این آیه؛ ترجمه‌های چندواژه‌ای به‌صورت یک گروه حفظ شده‌اند.','footnote'));
 if(!v){node.append(el('p','دادهٔ واژه‌های این آیه در دسترس نیست.','empty'));return node;}
 const grid=el('div',undefined,'word-grid');for(const group of v.groups){const card=el('article',undefined,'word-card');card.dataset.wordStart=group.start;card.dataset.wordLength=group.length;const title=el('h3',group.arabic);title.lang='ar';card.append(title,el('p',group.meaning));if(group.length>1)card.append(el('small',`معنی یک عبارت ${fa(group.length)}واژه‌ای`,'footnote'));const wordRoots=[...new Set(v.words.slice(group.start,group.start+group.length).map(w=>w.root).filter(Boolean))];if(wordRoots.length)card.append(el('p','ریشه: '+wordRoots.join('، '),'footnote'));grid.append(card);}node.append(grid);
 const words=selected.verses[ayah.number]?.words||[];if(words.length){const details=el('details');details.append(el('summary','معانی تکمیلی و کاربرد ریشه‌ها در واژه‌نامهٔ منصور'));const extra=el('div',undefined,'word-grid');for(const w of words){const card=el('article',undefined,'word-card');card.append(el('h3',w.arabic),el('p',w.meaning));const root=el('button',`کاربرد ریشهٔ ${w.rootDisplay||w.root}`);root.onclick=()=>showRoot(w.rootId).catch(e=>toast(e.message));card.append(root);extra.append(card);}details.append(extra);node.append(details);}return node;
 }
 $('words-search').oninput=()=>{searchLimit=50;search()};$('words-more').onclick=()=>{searchLimit+=50;search()};$('root-more').onclick=()=>{rootLimit+=100;renderOccurrences()};
 return {init,renderVerse,showRoot};
}
